//! Configuration and monitoring system for the knowledge library infrastructure\n//!\n//! This module provides comprehensive configuration management, runtime monitoring,\n//! and observability features for the knowledge library system.\n\nuse std::collections::HashMap;\nuse std::time::{Duration, SystemTime};\nuse std::sync::{Arc, atomic::{AtomicU64, AtomicUsize, AtomicBool, Ordering}};\nuse std::path::PathBuf;\nuse serde::{Serialize, Deserialize};\nuse parking_lot::RwLock;\nuse tokio::sync::broadcast;\n\n/// Comprehensive configuration for the knowledge infrastructure\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct KnowledgeInfrastructureConfig {\n    /// Performance tuning settings\n    pub performance: PerformanceConfig,\n    /// Memory management configuration\n    pub memory: MemoryConfig,\n    /// Concurrency settings\n    pub concurrency: ConcurrencyConfig,\n    /// AI integration configuration\n    pub ai_integration: AIIntegrationConfig,\n    /// Monitoring and observability settings\n    pub monitoring: MonitoringConfig,\n    /// Error handling configuration\n    pub error_handling: ErrorHandlingConfig,\n    /// Caching configuration\n    pub caching: CachingConfig,\n    /// Security settings\n    pub security: SecurityConfig,\n}\n\n/// Performance configuration settings\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct PerformanceConfig {\n    /// Target loading time in milliseconds (default: 100)\n    pub target_load_time_ms: u64,\n    /// Target lookup time in milliseconds (default: 1)\n    pub target_lookup_time_ms: u64,\n    /// Maximum memory usage in MB (default: 100)\n    pub max_memory_usage_mb: usize,\n    /// Enable performance profiling\n    pub enable_performance_profiling: bool,\n    /// Optimization level\n    pub optimization_level: OptimizationLevel,\n    /// Performance monitoring interval\n    pub monitoring_interval_ms: u64,\n    /// Performance alert thresholds\n    pub alert_thresholds: PerformanceThresholds,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub enum OptimizationLevel {\n    Minimal,\n    Balanced,\n    Aggressive,\n    Maximum,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct PerformanceThresholds {\n    pub load_time_warning_ms: u64,\n    pub load_time_critical_ms: u64,\n    pub lookup_time_warning_ms: f64,\n    pub lookup_time_critical_ms: f64,\n    pub memory_usage_warning_mb: usize,\n    pub memory_usage_critical_mb: usize,\n    pub cache_hit_rate_warning: f64,\n    pub error_rate_warning: f64,\n    pub error_rate_critical: f64,\n}\n\n/// Memory management configuration\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct MemoryConfig {\n    /// Memory allocation strategy\n    pub allocation_strategy: MemoryAllocationStrategy,\n    /// Garbage collection settings\n    pub gc_settings: GCSettings,\n    /// Memory monitoring configuration\n    pub monitoring: MemoryMonitoringConfig,\n    /// Memory limits and quotas\n    pub limits: MemoryLimits,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub enum MemoryAllocationStrategy {\n    Conservative,\n    Balanced,\n    Aggressive,\n    Custom { \n        initial_size_mb: usize,\n        growth_factor: f64,\n        max_size_mb: usize,\n    },\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct GCSettings {\n    pub enabled: bool,\n    pub trigger_threshold_mb: usize,\n    pub target_reduction_mb: usize,\n    pub max_gc_pause_ms: u64,\n    pub aggressive_gc_threshold: f64,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct MemoryMonitoringConfig {\n    pub sample_interval_ms: u64,\n    pub enable_detailed_tracking: bool,\n    pub track_allocations: bool,\n    pub memory_profiling: bool,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct MemoryLimits {\n    pub total_limit_mb: usize,\n    pub cache_limit_mb: usize,\n    pub buffer_limit_mb: usize,\n    pub working_set_limit_mb: usize,\n}\n\n/// Concurrency configuration\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct ConcurrencyConfig {\n    /// Maximum concurrent readers\n    pub max_concurrent_readers: usize,\n    /// Maximum concurrent writers\n    pub max_concurrent_writers: usize,\n    /// Lock timeout in milliseconds\n    pub lock_timeout_ms: u64,\n    /// Deadlock detection settings\n    pub deadlock_detection: DeadlockDetectionConfig,\n    /// Thread pool configuration\n    pub thread_pool: ThreadPoolConfig,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct DeadlockDetectionConfig {\n    pub enabled: bool,\n    pub detection_interval_ms: u64,\n    pub max_wait_time_ms: u64,\n    pub recovery_strategy: DeadlockRecoveryStrategy,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub enum DeadlockRecoveryStrategy {\n    AbortOldest,\n    AbortNewest,\n    AbortAll,\n    Timeout,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct ThreadPoolConfig {\n    pub core_threads: usize,\n    pub max_threads: usize,\n    pub keep_alive_ms: u64,\n    pub queue_size: usize,\n    pub thread_priority: ThreadPriority,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub enum ThreadPriority {\n    Low,\n    Normal,\n    High,\n    Critical,\n}\n\n/// AI integration configuration\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct AIIntegrationConfig {\n    /// Default token budget for AI prompts\n    pub default_token_budget: usize,\n    /// Context optimization settings\n    pub context_optimization: ContextOptimizationConfig,\n    /// Template configuration\n    pub templates: TemplateConfig,\n    /// Prompt caching settings\n    pub prompt_caching: PromptCachingConfig,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct ContextOptimizationConfig {\n    pub enabled: bool,\n    pub default_optimization_level: String,\n    pub max_context_size: usize,\n    pub compression_threshold: f64,\n    pub relevance_threshold: f64,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct TemplateConfig {\n    pub template_cache_size: usize,\n    pub custom_template_paths: Vec<PathBuf>,\n    pub enable_template_validation: bool,\n    pub template_compilation_cache: bool,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct PromptCachingConfig {\n    pub enabled: bool,\n    pub cache_size: usize,\n    pub ttl_seconds: u64,\n    pub cache_compression: bool,\n}\n\n/// Monitoring and observability configuration\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct MonitoringConfig {\n    /// Enable metrics collection\n    pub enable_metrics_collection: bool,\n    /// Metrics export interval in milliseconds\n    pub metrics_export_interval_ms: u64,\n    /// Enable distributed tracing\n    pub enable_distributed_tracing: bool,\n    /// Logging configuration\n    pub logging: LoggingConfig,\n    /// Performance alerts configuration\n    pub performance_alerts: Vec<PerformanceAlert>,\n    /// Health check configuration\n    pub health_checks: HealthCheckConfig,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct LoggingConfig {\n    pub log_level: LogLevel,\n    pub structured_logging: bool,\n    pub log_sampling_rate: f64,\n    pub error_stack_traces: bool,\n    pub performance_logging: bool,\n    pub audit_logging: bool,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub enum LogLevel {\n    Trace,\n    Debug,\n    Info,\n    Warn,\n    Error,\n    Fatal,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct PerformanceAlert {\n    pub name: String,\n    pub metric: String,\n    pub threshold: f64,\n    pub comparison: AlertComparison,\n    pub severity: AlertSeverity,\n    pub notification_channels: Vec<NotificationChannel>,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub enum AlertComparison {\n    GreaterThan,\n    LessThan,\n    Equals,\n    NotEquals,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub enum AlertSeverity {\n    Info,\n    Warning,\n    Critical,\n    Fatal,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub enum NotificationChannel {\n    Log,\n    Metrics,\n    Webhook { url: String },\n    Email { recipients: Vec<String> },\n    Slack { webhook_url: String },\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct HealthCheckConfig {\n    pub enabled: bool,\n    pub check_interval_ms: u64,\n    pub timeout_ms: u64,\n    pub healthy_threshold: usize,\n    pub unhealthy_threshold: usize,\n    pub checks: Vec<HealthCheck>,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct HealthCheck {\n    pub name: String,\n    pub check_type: HealthCheckType,\n    pub enabled: bool,\n    pub timeout_ms: u64,\n    pub critical: bool,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub enum HealthCheckType {\n    MemoryUsage { threshold_mb: usize },\n    CacheHitRate { threshold: f64 },\n    ResponseTime { threshold_ms: u64 },\n    ErrorRate { threshold: f64 },\n    LoadTest { requests_per_second: u64 },\n}\n\n/// Error handling configuration\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct ErrorHandlingConfig {\n    /// Circuit breaker configuration\n    pub circuit_breaker: CircuitBreakerConfig,\n    /// Retry configuration\n    pub retry: RetryConfig,\n    /// Fallback configuration\n    pub fallback: FallbackConfig,\n    /// Error reporting configuration\n    pub error_reporting: ErrorReportingConfig,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct CircuitBreakerConfig {\n    pub enabled: bool,\n    pub failure_threshold: u32,\n    pub timeout_ms: u64,\n    pub half_open_max_calls: u32,\n    pub metrics_window_ms: u64,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct RetryConfig {\n    pub max_attempts: u32,\n    pub initial_delay_ms: u64,\n    pub max_delay_ms: u64,\n    pub backoff_multiplier: f64,\n    pub jitter: bool,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct FallbackConfig {\n    pub enabled: bool,\n    pub fallback_timeout_ms: u64,\n    pub minimal_knowledge_base: bool,\n    pub cache_fallback: bool,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct ErrorReportingConfig {\n    pub enabled: bool,\n    pub include_stack_traces: bool,\n    pub include_system_info: bool,\n    pub sampling_rate: f64,\n    pub channels: Vec<NotificationChannel>,\n}\n\n/// Caching configuration\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct CachingConfig {\n    /// Pattern cache configuration\n    pub pattern_cache: CacheConfig,\n    /// Index cache configuration\n    pub index_cache: CacheConfig,\n    /// Template cache configuration\n    pub template_cache: CacheConfig,\n    /// Global cache settings\n    pub global_settings: GlobalCacheSettings,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct CacheConfig {\n    pub enabled: bool,\n    pub max_size: usize,\n    pub ttl_seconds: u64,\n    pub eviction_policy: EvictionPolicy,\n    pub compression: bool,\n    pub persistence: bool,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub enum EvictionPolicy {\n    Lru,\n    Lfu,\n    Fifo,\n    Random,\n    Ttl,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct GlobalCacheSettings {\n    pub total_memory_limit_mb: usize,\n    pub background_cleanup: bool,\n    pub cleanup_interval_ms: u64,\n    pub statistics_collection: bool,\n}\n\n/// Security configuration\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct SecurityConfig {\n    /// Enable security features\n    pub enabled: bool,\n    /// Input validation settings\n    pub input_validation: InputValidationConfig,\n    /// Access control settings\n    pub access_control: AccessControlConfig,\n    /// Audit logging settings\n    pub audit_logging: AuditLoggingConfig,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct InputValidationConfig {\n    pub enabled: bool,\n    pub max_input_size: usize,\n    pub allowed_patterns: Vec<String>,\n    pub blocked_patterns: Vec<String>,\n    pub sanitization: bool,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct AccessControlConfig {\n    pub enabled: bool,\n    pub rate_limiting: RateLimitingConfig,\n    pub authentication_required: bool,\n    pub authorization_required: bool,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct RateLimitingConfig {\n    pub enabled: bool,\n    pub requests_per_second: u64,\n    pub burst_size: u64,\n    pub window_size_ms: u64,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct AuditLoggingConfig {\n    pub enabled: bool,\n    pub log_all_operations: bool,\n    pub log_performance_metrics: bool,\n    pub log_errors: bool,\n    pub retention_days: u32,\n}\n\n/// Default configuration implementation\nimpl Default for KnowledgeInfrastructureConfig {\n    fn default() -> Self {\n        Self {\n            performance: PerformanceConfig::default(),\n            memory: MemoryConfig::default(),\n            concurrency: ConcurrencyConfig::default(),\n            ai_integration: AIIntegrationConfig::default(),\n            monitoring: MonitoringConfig::default(),\n            error_handling: ErrorHandlingConfig::default(),\n            caching: CachingConfig::default(),\n            security: SecurityConfig::default(),\n        }\n    }\n}\n\nimpl Default for PerformanceConfig {\n    fn default() -> Self {\n        Self {\n            target_load_time_ms: 100,\n            target_lookup_time_ms: 1,\n            max_memory_usage_mb: 100,\n            enable_performance_profiling: false,\n            optimization_level: OptimizationLevel::Balanced,\n            monitoring_interval_ms: 1000,\n            alert_thresholds: PerformanceThresholds::default(),\n        }\n    }\n}\n\nimpl Default for PerformanceThresholds {\n    fn default() -> Self {\n        Self {\n            load_time_warning_ms: 150,\n            load_time_critical_ms: 300,\n            lookup_time_warning_ms: 2.0,\n            lookup_time_critical_ms: 5.0,\n            memory_usage_warning_mb: 80,\n            memory_usage_critical_mb: 95,\n            cache_hit_rate_warning: 0.8,\n            error_rate_warning: 0.05,\n            error_rate_critical: 0.1,\n        }\n    }\n}\n\nimpl Default for MemoryConfig {\n    fn default() -> Self {\n        Self {\n            allocation_strategy: MemoryAllocationStrategy::Balanced,\n            gc_settings: GCSettings::default(),\n            monitoring: MemoryMonitoringConfig::default(),\n            limits: MemoryLimits::default(),\n        }\n    }\n}\n\nimpl Default for GCSettings {\n    fn default() -> Self {\n        Self {\n            enabled: true,\n            trigger_threshold_mb: 80,\n            target_reduction_mb: 20,\n            max_gc_pause_ms: 10,\n            aggressive_gc_threshold: 0.9,\n        }\n    }\n}\n\nimpl Default for MemoryMonitoringConfig {\n    fn default() -> Self {\n        Self {\n            sample_interval_ms: 5000,\n            enable_detailed_tracking: false,\n            track_allocations: false,\n            memory_profiling: false,\n        }\n    }\n}\n\nimpl Default for MemoryLimits {\n    fn default() -> Self {\n        Self {\n            total_limit_mb: 100,\n            cache_limit_mb: 50,\n            buffer_limit_mb: 20,\n            working_set_limit_mb: 30,\n        }\n    }\n}\n\nimpl Default for ConcurrencyConfig {\n    fn default() -> Self {\n        Self {\n            max_concurrent_readers: 100,\n            max_concurrent_writers: 10,\n            lock_timeout_ms: 5000,\n            deadlock_detection: DeadlockDetectionConfig::default(),\n            thread_pool: ThreadPoolConfig::default(),\n        }\n    }\n}\n\nimpl Default for DeadlockDetectionConfig {\n    fn default() -> Self {\n        Self {\n            enabled: true,\n            detection_interval_ms: 1000,\n            max_wait_time_ms: 10000,\n            recovery_strategy: DeadlockRecoveryStrategy::AbortOldest,\n        }\n    }\n}\n\nimpl Default for ThreadPoolConfig {\n    fn default() -> Self {\n        Self {\n            core_threads: num_cpus::get(),\n            max_threads: num_cpus::get() * 2,\n            keep_alive_ms: 60000,\n            queue_size: 1000,\n            thread_priority: ThreadPriority::Normal,\n        }\n    }\n}\n\nimpl Default for AIIntegrationConfig {\n    fn default() -> Self {\n        Self {\n            default_token_budget: 4000,\n            context_optimization: ContextOptimizationConfig::default(),\n            templates: TemplateConfig::default(),\n            prompt_caching: PromptCachingConfig::default(),\n        }\n    }\n}\n\nimpl Default for ContextOptimizationConfig {\n    fn default() -> Self {\n        Self {\n            enabled: true,\n            default_optimization_level: \"Advanced\".to_string(),\n            max_context_size: 2000,\n            compression_threshold: 0.8,\n            relevance_threshold: 0.7,\n        }\n    }\n}\n\nimpl Default for TemplateConfig {\n    fn default() -> Self {\n        Self {\n            template_cache_size: 100,\n            custom_template_paths: vec![],\n            enable_template_validation: true,\n            template_compilation_cache: true,\n        }\n    }\n}\n\nimpl Default for PromptCachingConfig {\n    fn default() -> Self {\n        Self {\n            enabled: true,\n            cache_size: 1000,\n            ttl_seconds: 3600,\n            cache_compression: false,\n        }\n    }\n}\n\nimpl Default for MonitoringConfig {\n    fn default() -> Self {\n        Self {\n            enable_metrics_collection: true,\n            metrics_export_interval_ms: 10000,\n            enable_distributed_tracing: false,\n            logging: LoggingConfig::default(),\n            performance_alerts: vec![],\n            health_checks: HealthCheckConfig::default(),\n        }\n    }\n}\n\nimpl Default for LoggingConfig {\n    fn default() -> Self {\n        Self {\n            log_level: LogLevel::Info,\n            structured_logging: true,\n            log_sampling_rate: 1.0,\n            error_stack_traces: true,\n            performance_logging: false,\n            audit_logging: false,\n        }\n    }\n}\n\nimpl Default for HealthCheckConfig {\n    fn default() -> Self {\n        Self {\n            enabled: true,\n            check_interval_ms: 30000,\n            timeout_ms: 5000,\n            healthy_threshold: 3,\n            unhealthy_threshold: 2,\n            checks: vec![\n                HealthCheck {\n                    name: \"memory_usage\".to_string(),\n                    check_type: HealthCheckType::MemoryUsage { threshold_mb: 90 },\n                    enabled: true,\n                    timeout_ms: 1000,\n                    critical: true,\n                },\n                HealthCheck {\n                    name: \"cache_hit_rate\".to_string(),\n                    check_type: HealthCheckType::CacheHitRate { threshold: 0.8 },\n                    enabled: true,\n                    timeout_ms: 1000,\n                    critical: false,\n                },\n            ],\n        }\n    }\n}\n\nimpl Default for ErrorHandlingConfig {\n    fn default() -> Self {\n        Self {\n            circuit_breaker: CircuitBreakerConfig::default(),\n            retry: RetryConfig::default(),\n            fallback: FallbackConfig::default(),\n            error_reporting: ErrorReportingConfig::default(),\n        }\n    }\n}\n\nimpl Default for CircuitBreakerConfig {\n    fn default() -> Self {\n        Self {\n            enabled: true,\n            failure_threshold: 5,\n            timeout_ms: 30000,\n            half_open_max_calls: 3,\n            metrics_window_ms: 60000,\n        }\n    }\n}\n\nimpl Default for RetryConfig {\n    fn default() -> Self {\n        Self {\n            max_attempts: 3,\n            initial_delay_ms: 100,\n            max_delay_ms: 5000,\n            backoff_multiplier: 2.0,\n            jitter: true,\n        }\n    }\n}\n\nimpl Default for FallbackConfig {\n    fn default() -> Self {\n        Self {\n            enabled: true,\n            fallback_timeout_ms: 1000,\n            minimal_knowledge_base: true,\n            cache_fallback: true,\n        }\n    }\n}\n\nimpl Default for ErrorReportingConfig {\n    fn default() -> Self {\n        Self {\n            enabled: true,\n            include_stack_traces: true,\n            include_system_info: true,\n            sampling_rate: 1.0,\n            channels: vec![NotificationChannel::Log],\n        }\n    }\n}\n\nimpl Default for CachingConfig {\n    fn default() -> Self {\n        Self {\n            pattern_cache: CacheConfig {\n                enabled: true,\n                max_size: 1000,\n                ttl_seconds: 3600,\n                eviction_policy: EvictionPolicy::Lru,\n                compression: false,\n                persistence: false,\n            },\n            index_cache: CacheConfig {\n                enabled: true,\n                max_size: 100,\n                ttl_seconds: 7200,\n                eviction_policy: EvictionPolicy::Lru,\n                compression: true,\n                persistence: true,\n            },\n            template_cache: CacheConfig {\n                enabled: true,\n                max_size: 100,\n                ttl_seconds: 1800,\n                eviction_policy: EvictionPolicy::Lru,\n                compression: false,\n                persistence: false,\n            },\n            global_settings: GlobalCacheSettings::default(),\n        }\n    }\n}\n\nimpl Default for GlobalCacheSettings {\n    fn default() -> Self {\n        Self {\n            total_memory_limit_mb: 50,\n            background_cleanup: true,\n            cleanup_interval_ms: 300000,\n            statistics_collection: true,\n        }\n    }\n}\n\nimpl Default for SecurityConfig {\n    fn default() -> Self {\n        Self {\n            enabled: true,\n            input_validation: InputValidationConfig::default(),\n            access_control: AccessControlConfig::default(),\n            audit_logging: AuditLoggingConfig::default(),\n        }\n    }\n}\n\nimpl Default for InputValidationConfig {\n    fn default() -> Self {\n        Self {\n            enabled: true,\n            max_input_size: 1024 * 1024, // 1MB\n            allowed_patterns: vec![],\n            blocked_patterns: vec![],\n            sanitization: true,\n        }\n    }\n}\n\nimpl Default for AccessControlConfig {\n    fn default() -> Self {\n        Self {\n            enabled: false,\n            rate_limiting: RateLimitingConfig::default(),\n            authentication_required: false,\n            authorization_required: false,\n        }\n    }\n}\n\nimpl Default for RateLimitingConfig {\n    fn default() -> Self {\n        Self {\n            enabled: false,\n            requests_per_second: 100,\n            burst_size: 10,\n            window_size_ms: 1000,\n        }\n    }\n}\n\nimpl Default for AuditLoggingConfig {\n    fn default() -> Self {\n        Self {\n            enabled: false,\n            log_all_operations: false,\n            log_performance_metrics: true,\n            log_errors: true,\n            retention_days: 30,\n        }\n    }\n}\n\n/// Configuration manager for the knowledge infrastructure\npub struct ConfigurationManager {\n    config: RwLock<KnowledgeInfrastructureConfig>,\n    config_watchers: RwLock<Vec<broadcast::Sender<ConfigurationChange>>>,\n    validation_enabled: AtomicBool,\n}\n\n#[derive(Debug, Clone, Serialize)]\npub struct ConfigurationChange {\n    pub timestamp: SystemTime,\n    pub section: String,\n    pub old_value: String,\n    pub new_value: String,\n    pub source: ConfigurationSource,\n}\n\n#[derive(Debug, Clone, Serialize)]\npub enum ConfigurationSource {\n    File,\n    Environment,\n    Runtime,\n    External,\n}\n\nimpl ConfigurationManager {\n    pub fn new(config: KnowledgeInfrastructureConfig) -> Self {\n        Self {\n            config: RwLock::new(config),\n            config_watchers: RwLock::new(Vec::new()),\n            validation_enabled: AtomicBool::new(true),\n        }\n    }\n    \n    pub fn get_config(&self) -> KnowledgeInfrastructureConfig {\n        self.config.read().clone()\n    }\n    \n    pub fn update_config(\n        &self,\n        section: &str,\n        update_fn: impl FnOnce(&mut KnowledgeInfrastructureConfig),\n    ) -> Result<(), ConfigurationError> {\n        let mut config = self.config.write();\n        let old_config = config.clone();\n        \n        update_fn(&mut config);\n        \n        if self.validation_enabled.load(Ordering::Relaxed) {\n            self.validate_config(&config)?;\n        }\n        \n        // Notify watchers\n        self.notify_config_change(section, &old_config, &config);\n        \n        Ok(())\n    }\n    \n    pub fn subscribe_to_changes(&self) -> broadcast::Receiver<ConfigurationChange> {\n        let (sender, receiver) = broadcast::channel(100);\n        self.config_watchers.write().push(sender);\n        receiver\n    }\n    \n    fn validate_config(&self, config: &KnowledgeInfrastructureConfig) -> Result<(), ConfigurationError> {\n        // Validate performance settings\n        if config.performance.target_load_time_ms == 0 {\n            return Err(ConfigurationError::InvalidValue {\n                field: \"performance.target_load_time_ms\".to_string(),\n                reason: \"Must be greater than 0\".to_string(),\n            });\n        }\n        \n        // Validate memory settings\n        if config.memory.limits.total_limit_mb == 0 {\n            return Err(ConfigurationError::InvalidValue {\n                field: \"memory.limits.total_limit_mb\".to_string(),\n                reason: \"Must be greater than 0\".to_string(),\n            });\n        }\n        \n        // Validate that cache limits don't exceed total memory\n        let total_cache_mb = config.caching.pattern_cache.max_size / (1024 * 1024) +\n                           config.caching.index_cache.max_size / (1024 * 1024) +\n                           config.caching.template_cache.max_size / (1024 * 1024);\n        \n        if total_cache_mb > config.memory.limits.total_limit_mb {\n            return Err(ConfigurationError::InvalidValue {\n                field: \"caching.total_memory\".to_string(),\n                reason: \"Total cache memory exceeds total memory limit\".to_string(),\n            });\n        }\n        \n        // Validate concurrency settings\n        if config.concurrency.max_concurrent_readers == 0 {\n            return Err(ConfigurationError::InvalidValue {\n                field: \"concurrency.max_concurrent_readers\".to_string(),\n                reason: \"Must be greater than 0\".to_string(),\n            });\n        }\n        \n        Ok(())\n    }\n    \n    fn notify_config_change(\n        &self,\n        section: &str,\n        old_config: &KnowledgeInfrastructureConfig,\n        new_config: &KnowledgeInfrastructureConfig,\n    ) {\n        let change = ConfigurationChange {\n            timestamp: SystemTime::now(),\n            section: section.to_string(),\n            old_value: serde_json::to_string(old_config).unwrap_or_default(),\n            new_value: serde_json::to_string(new_config).unwrap_or_default(),\n            source: ConfigurationSource::Runtime,\n        };\n        \n        let watchers = self.config_watchers.read();\n        for watcher in watchers.iter() {\n            let _ = watcher.send(change.clone());\n        }\n    }\n}\n\n#[derive(Debug, thiserror::Error)]\npub enum ConfigurationError {\n    #[error(\"Invalid configuration value for {field}: {reason}\")]\n    InvalidValue { field: String, reason: String },\n    \n    #[error(\"Configuration validation failed: {details}\")]\n    ValidationFailed { details: String },\n    \n    #[error(\"Configuration file error: {path} - {reason}\")]\n    FileError { path: String, reason: String },\n    \n    #[error(\"Serialization error: {reason}\")]\n    SerializationError { reason: String },\n}\n\n/// Monitoring system for the knowledge infrastructure\npub struct MonitoringSystem {\n    metrics: RwLock<HashMap<String, MetricValue>>,\n    alerts: RwLock<Vec<Alert>>,\n    health_status: RwLock<HealthStatus>,\n    notification_sender: broadcast::Sender<MonitoringEvent>,\n    collection_enabled: AtomicBool,\n    collection_interval: Duration,\n}\n\n#[derive(Debug, Clone, Serialize)]\npub enum MetricValue {\n    Counter(u64),\n    Gauge(f64),\n    Histogram { values: Vec<f64>, buckets: Vec<f64> },\n    Timer { duration_ms: u64, count: u64 },\n}\n\n#[derive(Debug, Clone, Serialize)]\npub struct Alert {\n    pub id: String,\n    pub name: String,\n    pub severity: AlertSeverity,\n    pub message: String,\n    pub timestamp: SystemTime,\n    pub metric: String,\n    pub value: f64,\n    pub threshold: f64,\n    pub acknowledged: bool,\n}\n\n#[derive(Debug, Clone, Serialize)]\npub struct HealthStatus {\n    pub overall_status: OverallHealthStatus,\n    pub component_statuses: HashMap<String, ComponentHealth>,\n    pub last_check: SystemTime,\n    pub check_duration_ms: u64,\n}\n\n#[derive(Debug, Clone, Serialize)]\npub enum OverallHealthStatus {\n    Healthy,\n    Degraded,\n    Unhealthy,\n    Critical,\n}\n\n#[derive(Debug, Clone, Serialize)]\npub struct ComponentHealth {\n    pub status: ComponentHealthStatus,\n    pub message: String,\n    pub last_check: SystemTime,\n    pub metrics: HashMap<String, f64>,\n}\n\n#[derive(Debug, Clone, Serialize)]\npub enum ComponentHealthStatus {\n    Healthy,\n    Warning,\n    Error,\n    Critical,\n}\n\n#[derive(Debug, Clone, Serialize)]\npub enum MonitoringEvent {\n    MetricUpdated {\n        metric_name: String,\n        value: MetricValue,\n        timestamp: SystemTime,\n    },\n    AlertTriggered {\n        alert: Alert,\n    },\n    HealthStatusChanged {\n        component: String,\n        old_status: ComponentHealthStatus,\n        new_status: ComponentHealthStatus,\n    },\n}\n\nimpl MonitoringSystem {\n    pub fn new(collection_interval: Duration) -> Self {\n        let (notification_sender, _) = broadcast::channel(1000);\n        \n        Self {\n            metrics: RwLock::new(HashMap::new()),\n            alerts: RwLock::new(Vec::new()),\n            health_status: RwLock::new(HealthStatus {\n                overall_status: OverallHealthStatus::Healthy,\n                component_statuses: HashMap::new(),\n                last_check: SystemTime::now(),\n                check_duration_ms: 0,\n            }),\n            notification_sender,\n            collection_enabled: AtomicBool::new(true),\n            collection_interval,\n        }\n    }\n    \n    pub fn record_metric(&self, name: &str, value: MetricValue) {\n        if !self.collection_enabled.load(Ordering::Relaxed) {\n            return;\n        }\n        \n        {\n            let mut metrics = self.metrics.write();\n            metrics.insert(name.to_string(), value.clone());\n        }\n        \n        // Send notification\n        let _ = self.notification_sender.send(MonitoringEvent::MetricUpdated {\n            metric_name: name.to_string(),\n            value,\n            timestamp: SystemTime::now(),\n        });\n    }\n    \n    pub fn get_metric(&self, name: &str) -> Option<MetricValue> {\n        self.metrics.read().get(name).cloned()\n    }\n    \n    pub fn get_all_metrics(&self) -> HashMap<String, MetricValue> {\n        self.metrics.read().clone()\n    }\n    \n    pub fn trigger_alert(&self, alert: Alert) {\n        {\n            let mut alerts = self.alerts.write();\n            alerts.push(alert.clone());\n            \n            // Keep only last 1000 alerts\n            if alerts.len() > 1000 {\n                alerts.remove(0);\n            }\n        }\n        \n        let _ = self.notification_sender.send(MonitoringEvent::AlertTriggered { alert });\n    }\n    \n    pub fn update_health_status(&self, component: &str, status: ComponentHealth) {\n        let old_status = {\n            let mut health = self.health_status.write();\n            let old_status = health.component_statuses\n                .get(component)\n                .map(|s| s.status.clone())\n                .unwrap_or(ComponentHealthStatus::Healthy);\n            \n            health.component_statuses.insert(component.to_string(), status.clone());\n            health.last_check = SystemTime::now();\n            \n            // Update overall status based on component statuses\n            health.overall_status = self.calculate_overall_status(&health.component_statuses);\n            \n            old_status\n        };\n        \n        if old_status != status.status {\n            let _ = self.notification_sender.send(MonitoringEvent::HealthStatusChanged {\n                component: component.to_string(),\n                old_status,\n                new_status: status.status,\n            });\n        }\n    }\n    \n    pub fn get_health_status(&self) -> HealthStatus {\n        self.health_status.read().clone()\n    }\n    \n    pub fn subscribe_to_events(&self) -> broadcast::Receiver<MonitoringEvent> {\n        self.notification_sender.subscribe()\n    }\n    \n    fn calculate_overall_status(&self, component_statuses: &HashMap<String, ComponentHealth>) -> OverallHealthStatus {\n        if component_statuses.is_empty() {\n            return OverallHealthStatus::Healthy;\n        }\n        \n        let mut has_critical = false;\n        let mut has_error = false;\n        let mut has_warning = false;\n        \n        for status in component_statuses.values() {\n            match status.status {\n                ComponentHealthStatus::Critical => has_critical = true,\n                ComponentHealthStatus::Error => has_error = true,\n                ComponentHealthStatus::Warning => has_warning = true,\n                ComponentHealthStatus::Healthy => {},\n            }\n        }\n        \n        if has_critical {\n            OverallHealthStatus::Critical\n        } else if has_error {\n            OverallHealthStatus::Unhealthy\n        } else if has_warning {\n            OverallHealthStatus::Degraded\n        } else {\n            OverallHealthStatus::Healthy\n        }\n    }\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n    \n    #[test]\n    fn test_default_configuration() {\n        let config = KnowledgeInfrastructureConfig::default();\n        assert_eq!(config.performance.target_load_time_ms, 100);\n        assert_eq!(config.memory.limits.total_limit_mb, 100);\n        assert!(config.monitoring.enable_metrics_collection);\n    }\n    \n    #[test]\n    fn test_configuration_manager() {\n        let config = KnowledgeInfrastructureConfig::default();\n        let manager = ConfigurationManager::new(config);\n        \n        let result = manager.update_config(\"performance\", |config| {\n            config.performance.target_load_time_ms = 200;\n        });\n        \n        assert!(result.is_ok());\n        \n        let updated_config = manager.get_config();\n        assert_eq!(updated_config.performance.target_load_time_ms, 200);\n    }\n    \n    #[test]\n    fn test_configuration_validation() {\n        let config = KnowledgeInfrastructureConfig::default();\n        let manager = ConfigurationManager::new(config);\n        \n        let result = manager.update_config(\"performance\", |config| {\n            config.performance.target_load_time_ms = 0; // Invalid\n        });\n        \n        assert!(result.is_err());\n    }\n    \n    #[test]\n    fn test_monitoring_system() {\n        let monitoring = MonitoringSystem::new(Duration::from_secs(1));\n        \n        monitoring.record_metric(\"test_counter\", MetricValue::Counter(42));\n        let metric = monitoring.get_metric(\"test_counter\");\n        \n        assert!(metric.is_some());\n        if let Some(MetricValue::Counter(value)) = metric {\n            assert_eq!(value, 42);\n        }\n    }\n    \n    #[test]\n    fn test_health_status_calculation() {\n        let monitoring = MonitoringSystem::new(Duration::from_secs(1));\n        \n        // Add healthy component\n        monitoring.update_health_status(\"component1\", ComponentHealth {\n            status: ComponentHealthStatus::Healthy,\n            message: \"All good\".to_string(),\n            last_check: SystemTime::now(),\n            metrics: HashMap::new(),\n        });\n        \n        let health = monitoring.get_health_status();\n        assert!(matches!(health.overall_status, OverallHealthStatus::Healthy));\n        \n        // Add unhealthy component\n        monitoring.update_health_status(\"component2\", ComponentHealth {\n            status: ComponentHealthStatus::Critical,\n            message: \"System failure\".to_string(),\n            last_check: SystemTime::now(),\n            metrics: HashMap::new(),\n        });\n        \n        let health = monitoring.get_health_status();\n        assert!(matches!(health.overall_status, OverallHealthStatus::Critical));\n    }\n}"